    std::stringstream html;

    // Headings
    std::regex heading_regex("^#{1,6} (.*)$", std::regex::icase);
    std::smatch heading_match;
    if (std::regex_search(markdown, heading_match, heading_regex)) {
        std::string heading_text = heading_match[1].str();
        std::string heading_level = std::to_string(heading_match.size() - 1);
        html << "<h" << heading_level << ">" << heading_text << "</h" << heading_level << ">\n";
        markdown.erase(0, heading_match.position() + heading_text.length() + 1);
    }

    // Bold and italic
    std::regex formatting_regex("\\*([^*]*)\\*(?:_| )|(?:_| )\\*([^*]*)\\*)|(?:\\_([^\\_]*?)\\_)(?:_| )|(?:_| )\\_([^\\_]*?)\\_");
    std::smatch formatting_match;
    while (std::regex_search(markdown, formatting_match, formatting_regex)) {
        std::string text = formatting_match[1].str() + formatting_match[2].str() + formatting_match[3].str() + formatting_match[4].str();
        std::string tag = (formatting_match.str(1).length() > 1) ? "strong" : (formatting_match.str(3).length() > 1) ? "em" : "";
        html << "<" << tag << ">" << text << "</" << tag << ">\n";
        markdown.erase(0, formatting_match.position() + formatting_match.length());
    }

    // Links
    std::regex link_regex("(?:\\[([^\\]]*)\\])\\(([^)]*)\\)", std::regex::icase);
    std::smatch link_match;
    while (std::regex_search(markdown, link_match, link_regex)) {
        std::string link_text = link_match[1].str();
        std::string link_url = link_match[2].str();
        html << "<a href=\"" << link_url << "\">" << link_text << "</a>\n";
        markdown.erase(0, link_match.position() + link_text.length() + link_url.length() + 4);
    }

    // Block quotes
    std::regex blockquote_regex("^> (.*)$", std::regex::icase);
    std::smatch blockquote_match;
    while (std::regex_search(markdown, blockquote_match, blockquote_regex)) {
        std::string blockquote_text = blockquote_match[1].str();
        html << "<blockquote>\n" << blockquote_text << "</blockquote>\n";
        markdown.erase(0, blockquote_match.position() + blockquote_text.length() + 2);
    }

    // Lists
    std::regex list_item_regex("^\\s*-\\s+(.*)$", std::regex::icase);
    std::regex list_regex("^\\s*(?:\\d+\\.\\s+)|(?:\\-*\\s+)|^\\s*(?:\\[[^\\]]*\\]\\s+)|(?:\\(\\S*\\)\\s+)|^\\s*(?:\\S+:\\s+)|(?:\\(\\s*\\S*\\s*\\)|\\[\\s*\\S*\\s*\\])\\s+(.*)$");
    std::smatch list_item_match, list_match;
    while (std::regex_search(markdown, list_item_match, list_item_regex)) {
        std::string list_text = list_item_match[1].str();
        std::string list_type;
        if (std::regex_search(markdown, list_match, list_regex)) {
            list_type = list_match.prefix().str();
            markdown.erase(0, list_match.position());
        }
        std::string list_html;
        if (list_type == "- ") {
            list_html = "<ul><li>" + list_text + "</li></ul>";
        } else if (list_type == "(\\d+). ") {
            list_html = "<ol start=\"" + list_match[1].str() + "\"><li>" + list_text + "</li></ol>";
        } else {
            list_html = "<ul><li>" + list_text + "</li></ul>";
        }
        html << list_html << "\n";
        markdown.erase(0, list_item_match.position() + list_text.length() + 2);
    }

    // Code blocks
    std::regex code_block_regex("^(`{3}|~{3})\\s*(. *)\\1$", std::regex::icase);
    std::smatch code_block_match;
    while (std::regex_search(markdown, code_block_match, code_block_regex)) {
        std::string code_text = code_block_match[2].str();
        std::string code_language = (code_block_match.str(1) == "```") ? "text" : "bash";
        html << "<pre><code class=\"" << code_language << "\">" << code_text << "</code></pre>\n";
        markdown.erase(0, code_block_match.position() + code_block_text.length() + 6);
    }

    // Paragraphs
    std::regex paragraph_regex("^([^\\n]+)(?=\\n|$)", std::regex::icase);
    std::smatch paragraph_match;
    while (std::regex_search(markdown, paragraph_match, paragraph_regex)) {
        std::string paragraph_text = paragraph_match[1].str();
        html << "<p>" << paragraph_text << "</p>\n";
        markdown.erase(0, paragraph_match.position() + paragraph_text.length());
    }

    // Remaining text
